if (/^(on|1|true|si|s[ií])$/i.test(String($env.BOT_TEXTOS_SOCIO || '').trim())) {
  for (const k in TEXTOS) {
    if (typeof TEXTOS[k] === 'string' && TEXTOS[k].indexOf('*VarMan Crew*') >= 0) {
