// Reemplaza {placeholders} por sus valores: T(TEXTOS.eligeReferencia, { ref: '05', precio: '$250.000' })
function T(plantilla, vars) {
  return String(plantilla).replace(/\{(\w+)\}/g, (m, k) => (vars && k in vars) ? String(vars[k]) : m);
}

// [AVISO-PLANTILLA] (flag BOT_AVISO_PLANTILLA, 2026-07-18) — avisos al DUEÑO
// como PLANTILLA aprobada de WhatsApp en vez de texto libre. POR QUÉ: la
// ventana de 24h — si el dueño no le escribió al bot en 24h, un texto libre se
// "acepta" (devuelve wamid, n8n lo ve verde) pero NUNCA llega al celular
// (código 131047). Las plantillas aprobadas SÍ llegan siempre. Requiere crear
// en Meta (WhatsApp Manager) una plantilla de UTILIDAD con el cuerpo:
//   🤖 *Aviso del bot VarMan*  +  {{1}}
// y poner en el .env: BOT_AVISO_PLANTILLA=on, WHATSAPP_PLANTILLA_AVISO=<nombre>
// y WHATSAPP_PLANTILLA_IDIOMA=<código EXACTO del idioma de la plantilla, ej es>.
// El texto del aviso viaja en {{1}} (Meta no permite saltos de línea en la
// variable → se aplanan con " | "). Con el flag OFF: texto libre, EXACTO a hoy.
// Vive aquí porque lo usan TRES nodos (Cerebro, barrido diario y Wompi).
function msjAvisoDueno(to, body) {
  const on = /^(on|1|true|si|s[ií])$/i.test(String($env.BOT_AVISO_PLANTILLA || '').trim());
  if (!on) return { messaging_product: 'whatsapp', to, type: 'text', text: { body } };
  const nombre = String($env.WHATSAPP_PLANTILLA_AVISO || 'aviso_bot').trim();
  const idioma = String($env.WHATSAPP_PLANTILLA_IDIOMA || 'es').trim();
  // la variable de una plantilla no admite \n, tabs ni 4+ espacios seguidos
  const plano = String(body || '').replace(/\s*\n+\s*/g, ' | ').replace(/\t/g, ' ')
    .replace(/ {4,}/g, '   ').trim().slice(0, 1000);
  return { messaging_product: 'whatsapp', to, type: 'template', template: {
    name: nombre,
    language: { code: idioma },
    components: [{ type: 'body', parameters: [{ type: 'text', text: plano }] }]
  } };
}

// Arma el payload de WhatsApp de una notificación pendiente (backlog 11-12:
// guía de envío y reseña post-entrega, docs de tiendas/varman/
// notificacionesPendientes que escribe la app). Devuelve null si es una
// reseña y no existe LINK_RESENAS_FB (se omite con registro, nunca rompe).
// Vive AQUÍ porque lo usan DOS nodos (el Cerebro y el trigger horario).
function mensajeDeNotificacion(to, x) {
  if (x.tipo === 'guia') {
    return { messaging_product: 'whatsapp', to, type: 'text', text: {
      body: T(TEXTOS.guiaEnvio, { transportadora: x.transportadora || '?', guia: x.guia || '?' })
    } };
  }
  if (x.tipo === 'resena') {
    const link = String($env.LINK_RESENAS_FB || '').trim();
    if (!link) return null;
    const nombre = String(x.cliente_nombre || '').trim();
    return { messaging_product: 'whatsapp', to, type: 'text', text: {
      body: T(TEXTOS.resenaPedido, {
        nombre: nombre ? ', ' + nombre : '',
        producto: x.producto || ('tenis de la Ref ' + (x.ref || '?')),
        link
      })
    } };
  }
  return null;
}

// ============ TRIGGER 5 MIN: rescate del modo conversa (~3 min de silencio) ============
// (flag BOT_MODO_CONVERSA, reunión socios 22-jul) Si el bot mostró info (ficha,
// precio, marca) y el cliente NO respondió en ~3 minutos, se le ofrece UNA sola
// vez el catálogo de la web para que compre por ahí. La salida va DIRECTO al
// nodo "Enviar a WhatsApp" (payloads válidos o []).
// - Con el flag OFF: devuelve [] SIN tocar Firestore (cero carga, cero cambios).
// - Ventana de 24h abierta por definición: convEsperaAt nace del último
//   mensaje del cliente (minutos antes).
// - UNA vez por sesión (convRescatado); las sesiones las limpia el barrido diario.
// textos.js va pegado ANTES de este archivo (TEXTOS y T disponibles).
const H = this.helpers;
const crypto = require('crypto');
const FS_BASE = 'https://firestore.googleapis.com/v1/projects/varman-crew/databases/(default)/documents';

const FLAG_MODO_CONVERSA = /^(on|1|true|si|s[ií])$/i.test(String($env.BOT_MODO_CONVERSA || '').trim());
if (!FLAG_MODO_CONVERSA) return [];

function b64url(buf) {
  return Buffer.from(buf).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}
async function tokenAdmin() {
  const sa = JSON.parse(Buffer.from($env.FIREBASE_SA_B64, 'base64').toString('utf8'));
  const now = Math.floor(Date.now() / 1000);
  const header = b64url(JSON.stringify({ alg: 'RS256', typ: 'JWT' }));
  const claims = b64url(JSON.stringify({
    iss: sa.client_email,
    scope: 'https://www.googleapis.com/auth/datastore',
    aud: 'https://oauth2.googleapis.com/token',
    iat: now, exp: now + 3600
  }));
  const signer = crypto.createSign('RSA-SHA256');
  signer.update(header + '.' + claims);
  const jwt = header + '.' + claims + '.' + b64url(signer.sign(sa.private_key));
  const r = await H.httpRequest({
    method: 'POST', url: 'https://oauth2.googleapis.com/token',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: 'grant_type=urn%3Aietf%3Aparams%3Aoauth%3Agrant-type%3Ajwt-bearer&assertion=' + jwt,
    timeout: 15000, json: true
  });
  return r.access_token;
}
function unwrap(v) {
  if (v == null) return null;
  if ('integerValue' in v) return parseInt(v.integerValue, 10);
  if ('doubleValue' in v) return v.doubleValue;
  if ('booleanValue' in v) return v.booleanValue;
  if ('stringValue' in v) return v.stringValue;
  return null;
}
function fromFs(doc) {
  if (!doc || !doc.fields) return null;
  const o = {};
  for (const k in doc.fields) o[k] = unwrap(doc.fields[k]);
  return o;
}
async function fsMerge(tok, path, obj) {
  const mask = Object.keys(obj).map((k) => 'updateMask.fieldPaths=' + encodeURIComponent(k)).join('&');
  const fields = {};
  for (const k in obj) {
    const v = obj[k];
    if (typeof v === 'number') fields[k] = { integerValue: String(Math.round(v)) };
    else if (typeof v === 'boolean') fields[k] = { booleanValue: v };
    else fields[k] = { stringValue: String(v) };
  }
  await H.httpRequest({ method: 'PATCH', url: FS_BASE + '/' + path + '?' + mask,
    headers: { Authorization: 'Bearer ' + tok, 'Content-Type': 'application/json' },
    body: { fields }, json: true, timeout: 15000 });
}
async function listar(tok, coleccion) {
  const docs = [];
  let pageToken = '';
  do {
    const url = FS_BASE + '/tiendas/varman/' + coleccion + '?pageSize=300' + (pageToken ? '&pageToken=' + encodeURIComponent(pageToken) : '');
    const r = await H.httpRequest({ method: 'GET', url,
      headers: { Authorization: 'Bearer ' + tok }, json: true, timeout: 20000 });
    for (const d of (r.documents || [])) {
      const o = fromFs(d) || {};
      o._id = d.name.split('/').pop();
      docs.push(o);
    }
    pageToken = r.nextPageToken || '';
  } while (pageToken);
  return docs;
}
function msjTexto(to, body) {
  return { messaging_product: 'whatsapp', to, type: 'text', text: { body } };
}

const MIN_MS = 60 * 1000;
const salida = [];
const tok = await tokenAdmin();
const dueno = String($env.OWNER_WHATSAPP || '').replace(/\D/g, '');

try {
  const sesiones = await listar(tok, 'botSesiones');
  for (const s of sesiones) {
    if (!s.convEsperaAt) continue;                 // no quedó esperando nada
    if (s.convRescatado === true) continue;        // UNA sola vez por sesión
    if (s.enHandoffAt) continue;                   // el humano la tiene: silencio
    if (!s._id || s._id === dueno) continue;       // al dueño no (pruebas)
    const edad = Date.now() - Date.parse(s.convEsperaAt);
    // entre 3 min y 12h (más viejo = conversación muerta, no molestar)
    if (isNaN(edad) || edad < 3 * MIN_MS || edad > 12 * 60 * MIN_MS) continue;
    // se marca ANTES de encolar: mejor perder un rescate que repetirlo
    await fsMerge(tok, 'tiendas/varman/botSesiones/' + s._id, { convRescatado: true });
    // en el paso de DATOS el empujón pide los 2 datos que faltan (no el
    // catálogo); en la conversa (sin pedido) va la invitación al catálogo web
    salida.push(msjTexto(s._id, s.estado === 'datos'
      ? TEXTOS.conversaRescateDatos
      : T(TEXTOS.conversaRescate, { url: TEXTOS.catalogoWebUrl })));
  }
} catch (e) {}

return salida.map((m) => ({ json: m }));

