if (/^(on|1|true|si|s[ií])$/i.test(String($env.BOT_CIERRE_CONFIANZA || '').trim())) {
  const lineaCC = '\n\n' + TEXTOS.cierreConfianzaLinea;
  TEXTOS.wompiLinkCliente += lineaCC;
