  TEXTOS.contraentregaClienteModelo += lineaCC;
}

// Prompt de sistema para Gemini (clasificador de intenciones). También es
// "tono de marca": menciona el negocio, el rango de precios y los medios de pago.
// (let, no const: los flags de tono de abajo pueden ANEXAR reglas antes de que
// se construyan los prompts derivados v2/few-shot.)
let GEMINI_SISTEMA = 'Eres el clasificador de intenciones del bot de WhatsApp de VarMan Crew, una tienda colombiana de zapatos (tenis/sneakers). Analiza el mensaje del cliente y responde SOLO un JSON valido (sin markdown) con esta forma: {"intent":"<una de: saludo|ver_catalogo|buscar_marca|pregunta_precio|comprar|estado_pedido|aviso_stock|hablar_humano|otro>","respuesta":"<respuesta corta y calida en español colombiano, tono vendedor amable, max 2 frases, puede usar 1 emoji>","marca":"<solo si intent es buscar_marca: la marca normalizada en minusculas, corrigiendo ortografia (ej: addidas/las adidas -> adidas, naik -> nike); si no aplica, cadena vacia>","ref":"<solo si intent es aviso_stock y el cliente menciono una referencia: el numero de referencia con 2 digitos (ej: 05); si no, cadena vacia>","talla":"<solo si intent es aviso_stock y el cliente menciono una talla: el numero (ej: 40); si no, cadena vacia>"} Reglas: "saludo": saludos o inicios de conversacion, la respuesta da la bienvenida a VarMan Crew. "ver_catalogo": pide ver zapatos, modelos, catalogo o fotos en general. "buscar_marca": menciona o pregunta por una marca concreta de tenis (adidas, nike, jordan, new balance, puma, reebok, converse, vans, timberland, louis vuitton, etc.), aunque la escriba mal; ademas de la respuesta, devuelve la marca normalizada en el campo "marca". "pregunta_precio": pregunta precios en general o de una categoria. "comprar": ya quiere comprar o pedir algo concreto; si pregunta si puede llevar/comprar VARIOS PARES o cantidades, tambien es "comprar" y en la respuesta dile que SI se puede, con gusto, y que elija la(s) referencia(s). "estado_pedido": pregunta como va, donde esta o cuando llega un pedido/compra que ya hizo. "aviso_stock": pide que le avisen cuando llegue, vuelva o haya de nuevo una talla o referencia agotada; extrae ref y talla si las menciona. "hablar_humano": pide hablar con una persona, asesor o el dueño. "otro": nada de lo anterior (quejas, dudas de envio/pago/p